#!/usr/bin/env python3
from __future__ import annotations
import html,json,hashlib
from pathlib import Path
from datetime import datetime,timezone
ATLAS=Path('/root/werkraum/_gpt/gesamtatlas')
PROOF=ATLAS/'endproduktbeweis';UI=PROOF/'UI';OUT=PROOF/'GROESSENWAHRHEIT'
INTAKE=Path('/root/werkraum_gesamtatlas_eingang')
UI.mkdir(parents=True,exist_ok=True);OUT.mkdir(parents=True,exist_ok=True)
sizes=json.loads((ATLAS/'GROESSENWAHRHEIT.json').read_text('utf-8'))
refresh=json.loads((ATLAS/'runtime/last_full_refresh.json').read_text('utf-8'))
snapshot=refresh['status'];roots=snapshot['scan']['roots']
intake=next(x for x in roots if x['name']=='gesamtatlas-eingang');zensi=next(x for x in roots if x['name']=='zensi')
tech=json.loads((PROOF/'EVIDENZ/GA-SIZE-TRUTH-INTAKE-TECHNICAL.json').read_text('utf-8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def human(n:int)->str:
 value=float(n);units=['B','KB','MB','GB','TB'];unit=units[0]
 for u in units:
  unit=u
  if abs(value)<1000 or u==units[-1]:break
  value/=1000
 return f'{value:.2f} {unit}'.replace('.',',')
status={'ok':True,'schema_version':'1.0','generated_utc':datetime.now(timezone.utc).isoformat(),'snapshot_revision':snapshot['revision'],'snapshot_generated_utc':snapshot['generated_utc'],'technical_test_id':tech['test_id'],'technical_checks':tech['check_count'],'sizes':sizes,'manual_intake':intake,'zensi':zensi,'truth_boundary':'Quelllandschaft, föderierter Außenkörper, erzeugter Atlas und tragbare Kapsel sind verschiedene Größen. Der manuelle Eingang macht Material auffindbar, aber nicht automatisch wahr oder kanonisch.','hashes':{'GROESSENWAHRHEIT.json':sha(ATLAS/'GROESSENWAHRHEIT.json'),'START_HIER.md':sha(INTAKE/'START_HIER.md'),'MANIFEST.json':sha(INTAKE/'MANIFEST.json')}}
(OUT/'STATUS.json').write_text(json.dumps(status,ensure_ascii=False,indent=2,sort_keys=True)+'\n','utf-8')
(OUT/'GROESSENWAHRHEIT.json').write_text(json.dumps(sizes,ensure_ascii=False,indent=2,sort_keys=True)+'\n','utf-8')
(OUT/'WURZEL_AUSSCHNITT.json').write_text(json.dumps({'gesamtatlas-eingang':intake,'zensi':zensi},ensure_ascii=False,indent=2,sort_keys=True)+'\n','utf-8')
(OUT/'EINGANG_START_HIER.md').write_text((INTAKE/'START_HIER.md').read_text('utf-8'),'utf-8')
(OUT/'EINGANG_MANIFEST.json').write_text((INTAKE/'MANIFEST.json').read_text('utf-8'),'utf-8')
css='''*{box-sizing:border-box}:root{color-scheme:dark;--bg:#0d0912;--panel:#1b1322;--panel2:#25182f;--ink:#f7effb;--muted:#cbbbd4;--line:#564263;--accent:#d8afff;--green:#9ce5bc;--amber:#ffd58c;--red:#ff9caa}body{margin:0;background:radial-gradient(circle at 12% 0,#2c193d,#0d0912 48%);color:var(--ink);font:16px/1.5 system-ui,sans-serif}header,main,footer{max-width:1200px;margin:auto;padding:1rem}a{color:#e1c2ff}h1{font-size:clamp(2.4rem,7vw,5rem);line-height:1;margin:.5rem 0 1rem;overflow-wrap:anywhere}.hero{padding:2.5rem 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem}.card,.panel{min-width:0;overflow-wrap:anywhere;background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:18px;padding:1rem}.number{font-size:clamp(1.8rem,5vw,3rem);font-weight:800;color:var(--accent)}.muted{color:var(--muted)}.green{color:var(--green)}.amber{color:var(--amber)}.red{color:var(--red)}code{white-space:normal}.equation{font-size:1.3rem;text-align:center;padding:1.5rem}.path{font-family:ui-monospace,monospace}.notice{border-left:4px solid var(--accent);padding-left:1rem}ul{padding-left:1.2rem}@media(max-width:680px){body{font-size:14px}header,main,footer{padding:.7rem}h1{font-size:2rem}.grid{grid-template-columns:1fr}}'''
source=human(sizes['source_landscape_logical_bytes']);direct=human(sizes['direct_source_logical_bytes']);fed=human(sizes['federated_external_logical_bytes']);workspace=human(sizes['atlas_workspace_logical_bytes_excluding_self_reports']);indexes=human(sizes['local_index_bytes']);capsule=human(sizes['portable_capsule_bytes']);intake_size=human(sizes['curated_intake_logical_bytes'])
def integer(n:int)->str:return f'{n:,}'.replace(',', '.')
body=f'''<section class="hero"><p class="muted">GA-SIZE-TRUTH · Snapshot {snapshot['revision']}</p><h1>54 GB Landschaft. <span style="color:var(--accent)">Nicht 54 GB Atlas.</span></h1><p>Der Atlas beschreibt und durchsucht eine große VPS-Landschaft. Er kopiert diese Landschaft nicht vollständig in sich hinein.</p></section><section class="grid"><article class="card" data-metric="source-landscape"><div class="number">{source}</div><h2>referenzierte Quelllandschaft</h2><p class="red"><strong>Nicht die Atlas-Dateigröße.</strong></p></article><article class="card" data-metric="federated"><div class="number">{fed}</div><h2>föderiertes Zensi</h2><p>Über <code>zensi.vault_search</code> und <code>zensi.vault_tree</code> erreichbar, nicht lokal volltextkopiert.</p></article><article class="card" data-metric="workspace"><div class="number">{workspace}</div><h2>erzeugter Atlas-Arbeitskörper</h2><p>Indizes, Organismus, Beweise und lokale Projektionen.</p></article><article class="card" data-metric="capsule"><div class="number">{capsule}</div><h2>private tragbare Kapsel</h2><p>Der WinSCP-Übergabekörper.</p></article></section><section class="panel equation"><strong>{source}</strong> Quellenlandschaft ≠ <strong>{workspace}</strong> Atlas ≠ <strong>{capsule}</strong> Kapsel</section><section class="grid"><article class="card"><h2>Direkte Quellen</h2><div class="number">{direct}</div><p>Werkraum, Sitzungen, Dokumente, Logs, Bilder und weitere lokal erschlossene Wurzeln.</p></article><article class="card"><h2>Lokale Indizes</h2><div class="number">{indexes}</div><p>Pfad-, Volltext- und Beziehungsindex, getrennt vom übrigen Arbeitskörper.</p></article><article class="card"><h2>Kuratierter Eingang</h2><div class="number">{intake_size}</div><p class="path">/root/werkraum_gesamtatlas_eingang</p><p>Aktuell klein, absichtlich. Daniel legt dort bewusst neue Primärquellen ab.</p></article></section><section class="panel" id="intake"><h2>Manuell Material hingeben</h2><p class="path">/root/werkraum_gesamtatlas_eingang</p><p>Dateien bleiben an dieser Stelle Originalquellen und werden beim Vollrefresh direkt indexiert:</p><ul><li>00_UNSORTIERT</li><li>DOKUMENTE</li><li>REVIEWS</li><li>IDEEN</li><li>KONZEPTE</li><li>AI_UEBERGABEN</li><li>QUELLEN</li></ul><p><a href="../GROESSENWAHRHEIT/EINGANG_START_HIER.md">Eingangsanleitung</a> · <a href="../GROESSENWAHRHEIT/EINGANG_MANIFEST.json">Eingangsmanifest</a></p><p class="notice"><strong>Wahrheitsgrenze:</strong> Ablage macht Material auffindbar. Sie macht es nicht automatisch wahr, aktuell, bestätigt oder kanonisch integriert.</p></section><section class="panel" id="zensi"><h2>Warum Zensi überhaupt auftaucht</h2><p>Zensi wurde bei der frühen Scope-Ausweitung als freigegebene VPS-Wurzel aufgenommen. Es bleibt ein föderierter Außenkörper: {integer(zensi['observed_path_count'])} beobachtete Einträge, aber nur {integer(zensi['indexed_path_count'])} lokale Strukturanker.</p><p>Der Gesamtatlas ist hier Wegweiser, nicht zweites Zensi-Lager.</p></section><section class="panel"><strong>Technischer Beweis:</strong> {tech['check_count']} Prüfungen · <a href="../EVIDENZ/GA-SIZE-TRUTH-INTAKE-TECHNICAL.json">Bericht</a> · <a href="../GROESSENWAHRHEIT/GROESSENWAHRHEIT.json">Maschinendaten</a></section>'''
page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Größenwahrheit und Eingang · Gesamtatlas</title><style>{css}</style></head><body><header><a href="index.html">Anforderungen</a> · <a href="ai-stroeme.html">AI-Ströme</a> · <a href="../GROESSENWAHRHEIT/STATUS.json">Status</a></header><main>{body}</main><footer><p class="muted">Private lokale Beweisoberfläche. Öffentliche Atlasroute bleibt geschlossen.</p></footer></body></html>'''
(UI/'groessenwahrheit.html').write_text(page,'utf-8')
index=UI/'index.html';text=index.read_text('utf-8')
if 'groessenwahrheit.html' not in text:
 text=text.replace('</header>',' · <a href="groessenwahrheit.html">Größenwahrheit</a></header>',1)
 index.write_text(text,'utf-8')
print(json.dumps({'ok':True,'ui':str(UI/'groessenwahrheit.html'),'status':str(OUT/'STATUS.json'),'snapshot_revision':snapshot['revision'],'sizes':{'source':source,'federated':fed,'workspace':workspace,'capsule':capsule}},ensure_ascii=False))
